import numpy as np
from scipy.optimize import minimize

def _get_lhs():
    try:
        from pyDOE2 import lhs as _lhs
        def lhs(n_samples, n_dim): return _lhs(n_samples, n_dim)
    except ImportError:
        try:
            from scipy.stats import qmc
            def lhs(n_samples, n_dim):
                return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
        except ImportError:
            raise ImportError("pyDOE2 or scipy required")
    return lhs

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng()
        self.cat_archive = []
        self._lhs = _get_lhs()
        self.stagnation_counter = 0
        self.last_best_f = float('inf')
        self.max_stagnation = 12

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        x = np.asarray(x, dtype=np.float64)
        x = np.clip(x, -1.0, 1.0)
        try:
            f = func(x)
        except Exception:
            f = float('inf')
        if not np.isfinite(f):
            f = float('inf')
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x.copy()
            self.stagnation_counter = 0
            self.last_best_f = f
        else:
            self.stagnation_counter += 1
        return f

    def _adaptive_cat_sample(self, n):
        if not self.cat_archive or self.evals < self.budget * 0.1:
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_vals = np.array([item[1] for item in self.cat_archive])
        valid_mask = np.isfinite(f_vals)
        if not np.any(valid_mask):
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        f_valid = f_vals[valid_mask]
        f_min = np.min(f_valid)
        temp = 0.3 + 0.2 * (self.evals / self.budget)
        weights = np.exp(-(f_valid - f_min) / (np.std(f_valid) + 1e-9 + temp))
        weights /= weights.sum()
        idxs = self.rng.choice(np.where(valid_mask)[0], size=n, p=weights)
        base_cats = np.array([self.cat_archive[i][0] for i in idxs])
        scale = 0.04 * np.exp(-2.0 * self.evals / self.budget) + 0.01
        return base_cats + self.rng.normal(0, scale, (n, 6))

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(12, min(45, self.budget // 3))
        pop = self._lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._adaptive_cat_sample(n_pop)
        fitness = np.array([self._evaluate(p, func) for p in pop])

        max_gen = max(5, min(30, self.budget // n_pop))
        f_div_history = []
        grad_history = []

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            valid_mask_g = np.isfinite(fitness)
            if not np.any(valid_mask_g):
                pop = self._lhs(n_samples=n_pop, n_dim=24)
                pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
                pop[:, 18:] = self._adaptive_cat_sample(n_pop)
                fitness = np.array([self._evaluate(p, func) for p in pop])
                self.stagnation_counter = 0
                continue

            if self.stagnation_counter > self.max_stagnation:
                n_reinit = max(4, n_pop // 4)
                idxs = self.rng.choice(n_pop, n_reinit, replace=False)
                for idx in idxs:
                    pop[idx] = self._lhs(1, 24)[0]
                    pop[idx] = np.clip(pop[idx] * 2.0 - 1.0, -1.0, 1.0)
                    pop[idx, 18:] = self._adaptive_cat_sample(1)[0]
                    fitness[idx] = self._evaluate(pop[idx], func)
                self.stagnation_counter = 0
                valid_mask_g = np.isfinite(fitness)

            valid_fitness = fitness[valid_mask_g]
            f_mean, f_std = np.mean(valid_fitness), np.std(valid_fitness)
            f_div_history.append(f_std / (np.abs(f_mean) + 1e-9))
            if len(f_div_history) > 10: f_div_history.pop(0)
            current_div = np.mean(f_div_history)

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            is_best_valid = np.isfinite(fitness[best_idx])

            grad_dir = None
            grad_norm = 0.0
            if grad_func and is_best_valid:
                try:
                    x_full_best = np.concatenate([x_best[:18], x_best[18:]])
                    g = grad_func(x_full_best)
                    if g is not None and len(g) == 18:
                        g_clean = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        grad_norm = np.linalg.norm(g_clean)
                        if grad_norm > 1e-12:
                            grad_dir = g_clean / grad_norm
                            grad_history.append(grad_norm)
                            if len(grad_history) > 8: grad_history.pop(0)
                except Exception: pass

            imp = max(0.0, self.last_best_f - self.best_f)
            alpha_grad = 0.0
            if grad_history and is_best_valid:
                avg_grad = np.mean(grad_history)
                alpha_grad = np.clip(imp * 2.5 / (avg_grad + 1e-9), 0.0, 0.25)

            base_F = 0.4 + 0.4 * current_div
            F = np.clip(base_F, 0.3, 1.0)
            CR = np.clip(0.6 + 0.1 * current_div, 0.6, 0.95)

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while len(set(idxs).intersection({i})) > 0:
                    idxs = self.rng.choice(n_pop, 3, replace=False)

                v = x_best.copy()
                diff = pop[idxs[1]] - pop[idxs[2]]
                mut_scale = F * (1.0 + self.rng.standard_normal() * 0.05)
                v[:18] += mut_scale * diff[:18]
                v[18:] += mut_scale * diff[18:]

                if grad_dir is not None and is_best_valid:
                    v[:18] += alpha_grad * grad_dir

                v = np.clip(v, -1.0, 1.0)

                cr_mask = self.rng.random(24) < CR
                trial = np.where(cr_mask, v, pop[i])
                trial = np.clip(trial, -1.0, 1.0)

                f_trial = self._evaluate(trial, func)

                if np.isinf(f_trial) and self.evals < self.budget and grad_dir is not None and is_best_valid:
                    step = 0.15 * np.maximum(1.0 - self.evals/self.budget, 0.1)
                    x_proj = x_best.copy()
                    x_proj[:18] = np.clip(x_best[:18] - step * grad_dir, -1.0, 1.0)
                    f_proj = self._evaluate(x_proj, func)
                    if np.isfinite(f_proj):
                        trial = x_proj
                        f_trial = f_proj
                    else:
                        trial = self._lhs(1, 24)[0]
                        trial = np.clip(trial * 2.0 - 1.0, -1.0, 1.0)
                        trial[18:] = self._adaptive_cat_sample(1)[0]
                        f_trial = self._evaluate(trial, func)

                if f_trial < fitness[i] or (not np.isfinite(fitness[i]) and np.isfinite(f_trial)):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        new_cat = trial[18:].copy()
                        if not any(np.allclose(c, new_cat, atol=0.05) for c, _ in self.cat_archive):
                            self.cat_archive.append((new_cat, f_trial))
                            if len(self.cat_archive) > 30: self.cat_archive.pop(0)

            # Periodic Micro-Local Search
            if gen % 3 == 0 and grad_func and self.evals < self.budget * 0.80:
                top_k = min(3, np.sum(valid_mask_g))
                if top_k > 0:
                    top_indices = np.argsort(fitness)[:top_k]
                    for idx in top_indices:
                        if self.evals >= self.budget: break
                        if not np.isfinite(fitness[idx]): continue
                        x0_c, x0_cat = pop[idx][:18].copy(), pop[idx][18:].copy()

                        def cost_wrap(x_c):
                            if self.evals >= self.budget: return float('inf')
                            return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)

                        def grad_wrap(x_c):
                            if self.evals >= self.budget: return np.zeros(18)
                            x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                            try:
                                g = grad_func(x_full)
                                return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                            except Exception: return np.zeros(18)

                        rem = max(5, min(25, int((self.budget - self.evals) * 0.3)))
                        try:
                            res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                           bounds=[(-1.0, 1.0)]*18,
                                           options={'maxfun': rem, 'ftol': 1e-10, 'gtol': 1e-10})
                            if np.isfinite(res.fun) and res.fun < fitness[idx]:
                                pop[idx] = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                                fitness[idx] = res.fun
                                if res.fun < self.best_f:
                                    self.best_f = res.fun
                                    self.best_x = pop[idx].copy()
                        except Exception: pass

        # Final fallback local search
        if self.evals < self.budget * 0.92 and grad_func:
            valid_indices = np.where(np.isfinite(fitness))[0]
            if len(valid_indices) > 0:
                best_idx = valid_indices[np.argmin(fitness[valid_indices])]
                x0 = pop[best_idx]
                x0_c, x0_cat = x0[:18].copy(), x0[18:].copy()

                def cost_wrap(x_c):
                    if self.evals >= self.budget: return float('inf')
                    return self._evaluate(np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat]), func)

                def grad_wrap(x_c):
                    if self.evals >= self.budget: return np.zeros(18)
                    x_full = np.concatenate([np.clip(x_c, -1.0, 1.0), x0_cat])
                    try:
                        g = grad_func(x_full)
                        return np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception: return np.zeros(18)

                rem = max(10, min(50, int((self.budget - self.evals) * 0.3)))
                try:
                    res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                                   bounds=[(-1.0, 1.0)]*18,
                                   options={'maxfun': rem, 'ftol': 1e-12, 'gtol': 1e-10})
                    if np.isfinite(res.fun) and res.fun < self.best_f:
                        self.best_f = res.fun
                        self.best_x = np.concatenate([np.clip(res.x, -1.0, 1.0), x0_cat])
                except Exception: pass

        return self.best_f, self.best_x
